1	import { Router } from "express";
2	import { bookings, findRoom, nextBookingId, bookingsForRoom } from "../store.js";
3	import { overlaps } from "../lib/overlap.js";
4	import { priceFor } from "../lib/price.js";
5	import { requireString, requireDate, requirePositiveInt, ValidationError } from "../lib/validate.js";
6	
7	export const bookingsRouter = Router();
8	
9	bookingsRouter.get("/", (req, res) => {
10	  const roomId = req.query.roomId;
11	  if (typeof roomId === "string") {
12	    res.json({ bookings: bookingsForRoom(roomId) });
13	    return;
14	  }
15	  res.json({ bookings });
16	});
17	
18	bookingsRouter.post("/", (req, res) => {
19	  try {
20	    const payload = req.body ?? {};
21	    const roomId = requireString(payload, "roomId");
22	    const who = requireString(payload, "who");
23	    const people = requirePositiveInt(payload, "people");
24	    const startsAt = requireDate(payload, "startsAt");
25	    const endsAt = requireDate(payload, "endsAt");
26	
27	    if (Date.parse(endsAt) <= Date.parse(startsAt)) {
28	      throw new ValidationError("endsAt doit etre posterieur a startsAt");
29	    }
30	
31	    const room = findRoom(roomId);
32	    if (!room) {
33	      throw new ValidationError(`salle inconnue : ${roomId}`);
34	    }
35	    if (people > room.capacity) {
36	      throw new ValidationError(`capacite depassee : ${people} > ${room.capacity}`);
37	    }
38	
39	    const clash = bookingsForRoom(roomId).find((b) =>
40	      overlaps(startsAt, endsAt, b.startsAt, b.endsAt)
41	    );
42	    if (clash) {
43	      res.status(409).json({ error: "creneau deja reserve", conflictsWith: clash.id });
44	      return;
45	    }
46	
47	    const booking = {
48	      id: nextBookingId(),
49	      roomId,
50	      who,
51	      people,
52	      startsAt,
53	      endsAt,
54	      price: priceFor(room, startsAt, endsAt)
55	    };
56	    bookings.push(booking);
57	    res.status(201).json({ booking });
58	  } catch (err) {
59	    if (err instanceof ValidationError) {
60	      res.status(err.status).json({ error: err.message });
61	      return;
62	    }
63	    throw err;
64	  }
65	});
66	
67	bookingsRouter.delete("/:id", (req, res) => {
68	  const index = bookings.findIndex((b) => b.id === req.params.id);
69	  if (index === -1) {
70	    res.status(404).json({ error: "reservation inconnue" });
71	    return;
72	  }
73	  const [removed] = bookings.splice(index, 1);
74	  res.json({ cancelled: removed.id });
75	});
