1	/**
2	 * Deux creneaux se chevauchent-ils ?
3	 *
4	 * Les bornes sont des dates ISO 8601. Un creneau est [debut, fin[.
5	 */
6	export function overlaps(aStart: string, aEnd: string, bStart: string, bEnd: string): boolean {
7	  const a1 = Date.parse(aStart);
8	  const a2 = Date.parse(aEnd);
9	  const b1 = Date.parse(bStart);
10	  const b2 = Date.parse(bEnd);
11	  return a1 < b2 && b1 < a2;
12	}
