1	// Tarification — repris du script de facturation, a nettoyer (ticket FACT-88).
2	import type { Room } from "../store.js";
3	
4	const WEEKEND_SURCHARGE = 20;
5	
6	export function isWeekend(startsAt: string): boolean {
7	  const day = new Date(startsAt).getUTCDay();
8	  return day === 0 || day === 6;
9	}
10	
11	export function hoursBetween(startsAt: string, endsAt: string): number {
12	  return (Date.parse(endsAt) - Date.parse(startsAt)) / 3600000;
13	}
14	
15	export function priceFor(room: Room, startsAt: string, endsAt: string): number {
16	  const base = room.hourlyRate * hoursBetween(startsAt, endsAt);
17	  if (isWeekend(startsAt)) {
18	    return base + WEEKEND_SURCHARGE;
19	  }
20	  return base;
21	}
