      { startsAt: "2026-10-04T09:00:00Z", endsAt: "2026-10-04T11:00:00Z" },
      { startsAt: "2026-10-06T00:00:00Z", endsAt: "2026-10-06T02:00:00Z" },
    ];
    expect(freeSlots(bookings, dayStart, dayEnd)).toEqual([wholeDay]);
  });

