1	import ok, { fail } from "./result.js";
2	import type { Result } from "./result.js";
3	
4	const DAY_MS = 86400000;
5	
6	export default function parseDay(date: unknown): Result<{ date: string; start: number; end: number }> {
7	  if (typeof date !== "string") {
8	    return fail("date manquante ou invalide : format attendu YYYY-MM-DD");
9	  }
10	  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
11	    return fail("date invalide : format attendu YYYY-MM-DD");
12	  }
13	  const start = Date.parse(`${date}T00:00:00.000Z`);
14	  if (Number.isNaN(start) || new Date(start).toISOString().slice(0, 10) !== date) {
15	    return fail("date impossible dans le calendrier");
16	  }
17	  return ok({ date, start, end: start + DAY_MS });
18	}
