1	type Slot = { startsAt: string; endsAt: string };
2	
3	export default function freeSlots(bookings: Slot[], dayStart: number, dayEnd: number): Slot[] {
4	  const busy = bookings
5	    .map((b) => [Math.max(Date.parse(b.startsAt), dayStart), Math.min(Date.parse(b.endsAt), dayEnd)])
6	    .filter(([start, end]) => start < end)
7	    .sort((a, b) => a[0] - b[0]);
8	
9	  const slots: Slot[] = [];
10	  let cursor = dayStart;
11	  for (const [start, end] of busy) {
12	    if (start > cursor) {
13	      slots.push({ startsAt: new Date(cursor).toISOString(), endsAt: new Date(start).toISOString() });
14	    }
15	    cursor = Math.max(cursor, end);
16	  }
17	  if (cursor < dayEnd) {
18	    slots.push({ startsAt: new Date(cursor).toISOString(), endsAt: new Date(dayEnd).toISOString() });
19	  }
20	  return slots;
21	}
